  'app/layout.tsx': { name: 'layout.tsx', fileExtension: 'tsx' },
  'app/page.tsx': { name: 'page.tsx', fileExtension: 'tsx' },
  'app/(dashboard)': {
    name: '(dashboard)',
    children: ['app/(dashboard)/dashboard'],
